setup.css:
body { font-family: Arial, Helvetica, sans-serif; padding: 1em; }
#window { width: 100px; overflow: hidden; position: relative; height: 60px; border: 1px solid #333; }
#strip { position: absolute; left: 0; margin: 0; padding: 0; list-style: none; width: 400px; }
#strip li { float: left; width: 100px; height: 60px; line-height: 60px; text-align: center; font-size: 2em; }

questions.solution:
$("#right").click( () => {
  if ($("#strip").is(":animated")) return;
  const left = parseInt($("#strip").css("left"));
  const newLeft = left <= -300 ? 0 : left - 100;
  $("#strip").animate({ left: newLeft + "px" }, 150);
});
